<template><view class="page"><view class="card"><view class="title">授权健康顾问</view><input v-model="keyword" placeholder="搜索健康顾问姓名/手机号" @input="search"/><view v-for="o in options" :key="o.value" :class="['option',{selected:String(form.granteeUserId)===String(o.value)}]" @tap="form.granteeUserId=o.value">{{o.label}}</view><view class="scopes"><label v-for="s in scopes" :key="s.value"><checkbox :value="s.value" :checked="form.scopeCodes.indexOf(s.value)>-1" @tap.prevent="toggle(s.value)"/>{{s.label}}</label></view><label class="export"><checkbox :checked="form.allowExport" @tap.prevent="form.allowExport=!form.allowExport"/>允许该健康顾问导出已授权范围的数据</label><button @tap="submit">确认授权</button></view><view class="title list-title">授权记录</view><view v-for="item in list" :key="item.id" class="card"><view class="row"><b>{{item.granteeName||item.granteeUserId}}</b><text>{{item.statusText||item.status}}</text></view><view class="scope">{{item.scopeCodes}} · {{item.allowExport?'允许导出':'禁止导出'}}</view><button v-if="item.status==='ACTIVE'" size="mini" @tap="revoke(item)">撤销授权</button></view></view></template><script>import{getHealthAuthorizations,getHealthAdvisorOptions,createHealthAuthorization,revokeHealthAuthorization}from'@/api/health.js';export default{data(){return{keyword:'',options:[],list:[],form:{granteeUserId:'',scopeCodes:['GLUCOSE'],allowExport:false},scopes:[{label:'档案',value:'PROFILE'},{label:'血糖',value:'GLUCOSE'},{label:'饮食',value:'DIET'},{label:'运动',value:'EXERCISE'},{label:'用药',value:'MEDICINE'}]}},onShow(){this.load();this.search()},methods:{load(){getHealthAuthorizations().then(r=>this.list=(r&&r.data)||r||[])},search(){getHealthAdvisorOptions({keyword:this.keyword,limit:20}).then(r=>this.options=(r&&r.data)||r||[])},toggle(v){const i=this.form.scopeCodes.indexOf(v);i>-1?this.form.scopeCodes.splice(i,1):this.form.scopeCodes.push(v)},submit(){if(!this.form.granteeUserId||!this.form.scopeCodes.length)return uni.showToast({title:'请选择健康顾问和授权范围',icon:'none'});createHealthAuthorization(this.form).then(()=>{uni.showToast({title:'授权成功'});this.load()})},revoke(item){uni.showModal({title:'确认撤销授权',success:r=>{if(r.confirm)revokeHealthAuthorization(item.id,'用户主动撤销').then(()=>this.load())}})}}}</script><style lang="scss" scoped>.page{min-height:100vh;background:#f6f7f8;padding:24rpx}.card{background:#fff;border-radius:20rpx;padding:26rpx;margin-bottom:18rpx}.title{font-size:31rpx;font-weight:600;margin-bottom:20rpx}.list-title{margin:30rpx 8rpx 18rpx}.card input{height:80rpx;border-bottom:1rpx solid #eee}.option{padding:20rpx;border-bottom:1rpx solid #f1f1f1}.selected{color:#19bf9b;font-weight:600}.scopes{display:flex;flex-wrap:wrap;gap:20rpx;margin:24rpx 0}.export{display:block;margin:20rpx 0;color:#555;font-size:24rpx}.card button{background:#19bf9b;color:#fff}.row{display:flex;justify-content:space-between}.scope{color:#777;margin:18rpx 0;font-size:24rpx}</style>